from scipy.optimize import least_squares
import itertools, warnings
warnings.filterwarnings('ignore')
F={'1':np.ones_like(t),'t':t,'t2':t**2,'sqrtt':np.sqrt(t),'1/t':1/t,'exp-t':np.exp(-t),'expt':np.exp(t),'sint':np.sin(t),'cost':np.cos(t),'logt':np.log(t)}
G={'1':np.ones_like(v),'v':v,'v2':v**2,'1/v':1/v,'1/v2':1/v**2,'exp-v':np.exp(-v),'expv':np.exp(v),'sinv':np.sin(v),'cosv':np.cos(v),'v3':v**3,'sqrtv':np.sqrt(v),'logv':np.log(v),'exp-v2':np.exp(-v**2)}
H={'1':np.ones_like(x),'x':x,'x2':x**2,'exp-x2':np.exp(-x**2),'1/x':1/x,'expx':np.exp(x),'sinx':np.sin(x),'cosx':np.cos(x),'1/(1+x)':1/(1+x),'exp-x':np.exp(-x)}
results=[]
def base(p): return p[0]*t + p[1]/(1+p[2]*x)/v + p[3]*np.exp(-p[4]*x**2)
for (fn,f),(gn,g),(hn,h) in itertools.product(F.items(),G.items(),H.items()):
    z=f*g*h
    if np.std(z)<1e-12: continue
    def mm(p): return base(p)+p[5]*z
    try:
        r=min([least_squares(lambda p: mm(p)-dv_dt, np.random.RandomState(s).uniform(-2,2,6)) for s in range(3)], key=lambda r:r.cost)
        results.append((np.mean(r.fun**2)/np.var(dv_dt),fn,gn,hn))
    except Exception as e:
        pass
results.sort()
for r_ in results[:10]: print(r_)

